    global pow_
    pow_ = [0] * k
    pow_[0] = 1
    for i in range(1, k):
        pow_[i] = (n * pow_[i - 1]) % mod

def gcd_range(n):
    gcd_val = 1
    for i in range(1, n + 1):
        gcd_val = math.gcd(gcd_val, i)
    return gcd_val

def gcd(a, b):
    return a * b // ggt(a, b)

def ggt(a, b):
    if a < b:
        return ggt(b, a)
    if b == 0:
        return a
    return ggt(b, a % b)

